  function taipeiParts(date=new Date()){
    const parts=new Intl.DateTimeFormat('en-CA',{timeZone:CONFIG.timeZone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(date);
    const values=Object.fromEntries(parts.filter(part=>part.type!=='literal').map(part=>[part.type,part.value]));
    return {year:+values.year,month:+values.month,day:+values.day,hour:+values.hour,minute:+values.minute};
  }
  function isoDate(date){return `${date.getUTCFullYear()}-${pad(date.getUTCMonth()+1)}-${pad(date.getUTCDate())}`;}
  function currentWeek(){
    const today=taipeiParts();
    const date=new Date(Date.UTC(today.year,today.month-1,today.day));
    const monday=new Date(date); monday.setUTCDate(date.getUTCDate()-((date.getUTCDay()+6)%7));
    const dates=Array.from({length:7},(_,index)=>{const item=new Date(monday);item.setUTCDate(monday.getUTCDate()+index);return item;});
    return {dates,start:isoDate(dates[0]),end:isoDate(dates[6]),today:`${today.year}-${pad(today.month)}-${pad(today.day)}`};
  }
  function cellText(cell){if(!cell)return '';return String(cell.f??cell.v??'').trim();}
  function parseHeaderDate(value,baseYear,firstMonth){
    const match=String(value||'').trim().match(/^(\d{1,2})\s*[\/.-]\s*(\d{1,2})$/);
    if(!match)return '';
    const month=+match[1],day=+match[2]; if(month<1||month>12||day<1||day>31)return '';
    let year=baseYear; if(firstMonth>=11&&month<=2)year+=1; if(firstMonth<=2&&month>=11)year-=1;
    return `${year}-${pad(month)}-${pad(day)}`;
  }
